ValidationRule.errorConditionFormula:
OR( AND( IsSystemGeneratedRecord = TRUE, ISPICKVAL(Status__c, "Re-Opened"), ISPICKVAL($User.User_Type__c ,"ESG Team"), OR (ISBLANK(Comments__c), (ISBLANK(Due_Date__c) || (Due_Date__c < TODAY() ))) ) ,
AND( IsSystemGeneratedRecord = FALSE, ISPICKVAL(Status__c, "Re-Opened"), OR( ISPICKVAL($User.User_Type__c ,"ESG Team"), ISPICKVAL($User.User_Type__c ,"Data Modeller") ), OR (ISBLANK(Comments__c), (ISBLANK(Due_Date__c) || (Due_Date__c < TODAY() ))) )
)
